<?php
namespace App\Features\Vehicles\Controllers;
use App\Features\Vehicles\Repositories\VehicleRepository; use App\Features\Vehicles\Requests\VehicleRequest; use App\Features\Vehicles\Services\VehicleService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class VehicleController { public function __construct(private VehicleRepository $vehicles,private VehicleService $service){} private function tenant(Request $r): string{return (string)$r->user()->tenant_id;} public function index(Request $r): JsonResponse{$r->user()->can('vehicle.view')||abort(403);return response()->json(['success'=>true,'data'=>$this->vehicles->paginate($r->query(),$this->tenant($r))]);} public function store(VehicleRequest $r): JsonResponse{return response()->json(['success'=>true,'data'=>$this->service->create($r->validated(),$this->tenant($r),$r->user()->id)],201);} public function show(Request $r,string $vehicle): JsonResponse{$r->user()->can('vehicle.view')||abort(403);return response()->json(['success'=>true,'data'=>$this->vehicles->find($vehicle,$this->tenant($r))]);} public function update(VehicleRequest $r,string $vehicle): JsonResponse{return response()->json(['success'=>true,'data'=>$this->service->update($this->vehicles->find($vehicle,$this->tenant($r)),$r->validated(),$r->user()->id)]);} public function destroy(Request $r,string $vehicle): JsonResponse{$r->user()->can('vehicle.delete')||abort(403);$this->vehicles->find($vehicle,$this->tenant($r))->delete();return response()->json(['success'=>true,'data'=>null]);} }
